/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_acciones_after_update` AFTER UPDATE ON `acciones` FOR EACH ROW BEGIN
  
  IF OLD.estado != NEW.estado THEN
    INSERT INTO historial_acciones 
      (accion_id, tipo_evento, estado_anterior, estado_nuevo, descripcion, realizado_por)
    VALUES 
      (NEW.id, 'cambio_estado', OLD.estado, NEW.estado, 
       CONCAT('Cambio de estado de ', OLD.estado, ' a ', NEW.estado),
       NEW.updated_by);
  END IF;
  
  
  IF OLD.persona_id != NEW.persona_id THEN
    INSERT INTO historial_acciones 
      (accion_id, tipo_evento, descripcion, realizado_por)
    VALUES 
      (NEW.id, 'cambio_titular', 
       CONCAT('Cambio de titular de persona_id ', OLD.persona_id, ' a ', NEW.persona_id),
       NEW.updated_by);
  END IF;
END */;;
DELIMITER ;
