  `tipomiembro` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Tipo de Postulado',
  `cedula` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Cedula del Postulado',
  `primer_nombre` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `segundo_nombre` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `primer_apellido` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `segundo_apellido` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `accion` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Accion a Consultar',
  `correo_electronico` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `profesion` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Profesion del Postulado',
  `tipo_referencia` enum('SOCIO','EMPRESA') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `referencia_id` int DEFAULT NULL,
  `foto` mediumblob COMMENT 'Foto del Postulado',
  `nacionalidad_id` int DEFAULT NULL COMMENT 'FK a nacionalidades',
  `en_votacion` tinyint(1) DEFAULT '0' COMMENT 'Indica si el postulado participa en la votaciÃ³n actual',
  PRIMARY KEY (`cedula`) USING BTREE,
  KEY `fk_postulados_nacionalidad` (`nacionalidad_id`),
  CONSTRAINT `fk_postulados_nacionalidad` FOREIGN KEY (`nacionalidad_id`) REFERENCES `nacionalidades` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
