/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `tr_usuarios_update` AFTER UPDATE ON `usuarios` FOR EACH ROW BEGIN
    DECLARE v_evento VARCHAR(50);
    DECLARE v_detalle VARCHAR(200);

    IF OLD.bloqueado <> NEW.bloqueado THEN
        IF NEW.bloqueado = 1 THEN
            SET v_evento  = 'USUARIO_BLOQUEADO';
            SET v_detalle = CONCAT('El usuario "', NEW.usuario, '" fue BLOQUEADO. Acceso al sistema suspendido.');
        ELSE
            SET v_evento  = 'USUARIO_DESBLOQUEADO';
            SET v_detalle = CONCAT('El usuario "', NEW.usuario, '" fue DESBLOQUEADO. Acceso restaurado.');
        END IF;
    ELSEIF OLD.tipo_usuario_id <> NEW.tipo_usuario_id THEN
        SET v_evento  = 'CAMBIO_ROL';
        SET v_detalle = CONCAT('Cambio de rol (tipo_usuario_id): ', OLD.tipo_usuario_id, ' -> ', NEW.tipo_usuario_id);
    ELSE
        SET v_evento  = 'ACTUALIZACION_GENERAL';
        SET v_detalle = CONCAT('Datos del usuario "', NEW.usuario, '" actualizados.');
    END IF;

    INSERT INTO `auditoria_operaciones` (tabla, operacion, id_registro, valores_anteriores, valores_nuevos, usuario_id, usuario_nombre)
    VALUES (
        'usuarios', 'UPDATE', OLD.usuario,
        JSON_OBJECT(
            'tipo_usuario_id',   OLD.tipo_usuario_id,
            'puesto_trabajo_id', OLD.puesto_trabajo_id,
            'bloqueado',         OLD.bloqueado
        ),
        JSON_OBJECT(
            'tipo_usuario_id',   NEW.tipo_usuario_id,
            'puesto_trabajo_id', NEW.puesto_trabajo_id,
            'bloqueado',         NEW.bloqueado,
            'evento',            v_evento,
            'detalle',           v_detalle
        ),
        @current_user_id, CURRENT_USER()
    );
END */;;
DELIMITER ;
