CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_bloquear_usuario`(
            IN p_usuario VARCHAR(50),
            IN p_bloqueado TINYINT(1)
        )
BEGIN
            UPDATE usuarios 
            SET bloqueado = p_bloqueado 
            WHERE usuario = p_usuario;
        END ;;
