CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_crear_postulado`(
        IN p_tipomiembro VARCHAR(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci, 
        IN p_cedula VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci, 
        IN p_nacionalidad_id INT, 
        IN p_primer_nombre VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci, 
        IN p_segundo_nombre VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci, 
        IN p_primer_apellido VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci, 
        IN p_segundo_apellido VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci, 
        IN p_correo_electronico VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci, 
        IN p_profesion VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci, 
        IN p_tipo_referencia ENUM('SOCIO','EMPRESA'), 
        IN p_referencia_id INT, 
        IN p_foto MEDIUMBLOB
    )
BEGIN
        DECLARE v_existe_postulado INT DEFAULT 0;
        DECLARE v_existe_referencia INT DEFAULT 0;
        DECLARE v_nombre_completo VARCHAR(400);
        DECLARE v_referencia_nombre VARCHAR(200);
        
        IF p_cedula IS NULL OR TRIM(p_cedula) = '' THEN
            SIGNAL SQLSTATE '45000' 
            SET MESSAGE_TEXT = 'Error: La cÃ©dula es obligatoria.';
        END IF;
        
        IF p_primer_nombre IS NULL OR TRIM(p_primer_nombre) = '' THEN
            SIGNAL SQLSTATE '45000' 
            SET MESSAGE_TEXT = 'Error: El primer nombre es obligatorio.';
        END IF;
        
        IF p_primer_apellido IS NULL OR TRIM(p_primer_apellido) = '' THEN
            SIGNAL SQLSTATE '45000' 
            SET MESSAGE_TEXT = 'Error: El primer apellido es obligatorio.';
        END IF;
        
        IF p_tipomiembro NOT IN ('PRINCIPAL', 'SUPLENTE', 'VOCAL 1', 'VOCAL 2', 'VOCAL 3', 
                                 'PRESIDENTE', 'VICEPRESIDENTE', 'SECRETARIO', 'TESORERO') THEN
            SIGNAL SQLSTATE '45000' 
            SET MESSAGE_TEXT = 'Error: Tipo de miembro no vÃ¡lido.';
        END IF;
        
        SELECT COUNT(*) INTO v_existe_postulado 
        FROM postulados 
        WHERE cedula = p_cedula;
        
        IF v_existe_postulado > 0 THEN
            SIGNAL SQLSTATE '45000' 
            SET MESSAGE_TEXT = 'Error: Ya existe un postulado con esta cÃ©dula.';
        END IF;
        
        IF p_tipo_referencia IS NOT NULL AND p_referencia_id IS NOT NULL THEN
            IF p_tipo_referencia = 'SOCIO' THEN
                SELECT COUNT(*) INTO v_existe_referencia
                FROM acciones a
                JOIN personas p ON a.persona_id = p.id
                WHERE p.id = p_referencia_id AND a.estado = 'ACTIVO';
                
                IF v_existe_referencia = 0 THEN
                    SIGNAL SQLSTATE '45000' 
                    SET MESSAGE_TEXT = 'Error: El socio de referencia no existe o no estÃ¡ activo.';
                END IF;
                
            ELSEIF p_tipo_referencia = 'EMPRESA' THEN
                SELECT COUNT(*) INTO v_existe_referencia
                FROM empresas
                WHERE id_empresa = p_referencia_id;
                
                IF v_existe_referencia = 0 THEN
                    SIGNAL SQLSTATE '45000' 
                    SET MESSAGE_TEXT = 'Error: La empresa de referencia no existe.';
                END IF;
            END IF;
        END IF;
        
        INSERT INTO postulados (
            tipomiembro,
            cedula,
            nacionalidad_id,
            primer_nombre,
            segundo_nombre,
            primer_apellido,
            segundo_apellido,
            correo_electronico,
            profesion,
            tipo_referencia,
            referencia_id,
            foto,
            en_votacion
        ) VALUES (
            UPPER(TRIM(p_tipomiembro)),
            TRIM(p_cedula),
            COALESCE(p_nacionalidad_id, 1),
            TRIM(p_primer_nombre),
            TRIM(COALESCE(p_segundo_nombre, '')),
            TRIM(p_primer_apellido),
            TRIM(COALESCE(p_segundo_apellido, '')),
            TRIM(COALESCE(p_correo_electronico, '')),
            TRIM(COALESCE(p_profesion, '')),
            p_tipo_referencia,
            p_referencia_id,
            p_foto,
            0  
        );
        
        SET v_nombre_completo = CONCAT_WS(' ', 
            TRIM(p_primer_nombre), 
            TRIM(COALESCE(p_segundo_nombre, '')), 
            TRIM(p_primer_apellido), 
            TRIM(COALESCE(p_segundo_apellido, ''))
        );
        
        IF p_tipo_referencia = 'SOCIO' AND p_referencia_id IS NOT NULL THEN
            SELECT CONCAT(CONCAT_WS(' ', p.primer_nombre, p.primer_apellido), ' (AcciÃ³n: ', a.numero_accion, ')')
            INTO v_referencia_nombre
            FROM personas p
            JOIN acciones a ON p.id = a.persona_id
            WHERE p.id = p_referencia_id
            LIMIT 1;
            
        ELSEIF p_tipo_referencia = 'EMPRESA' AND p_referencia_id IS NOT NULL THEN
            SELECT CONCAT(nombre_empresa, ' (RIF: ', rif_empresa, ')')
            INTO v_referencia_nombre
            FROM empresas
            WHERE id_empresa = p_referencia_id
            LIMIT 1;
        END IF;
        
        SELECT 
            p_cedula AS cedula,
            COALESCE(p_nacionalidad_id, 1) AS nacionalidad_id,
            v_nombre_completo AS nombre_completo,
            TRIM(p_primer_nombre) AS primer_nombre,
            TRIM(COALESCE(p_segundo_nombre, '')) AS segundo_nombre,
            TRIM(p_primer_apellido) AS primer_apellido,
            TRIM(COALESCE(p_segundo_apellido, '')) AS segundo_apellido,
            UPPER(TRIM(p_tipomiembro)) AS tipomiembro,
            TRIM(COALESCE(p_correo_electronico, '')) AS correo_electronico,
            TRIM(COALESCE(p_profesion, '')) AS profesion,
            p_tipo_referencia AS tipo_referencia,
            p_referencia_id AS referencia_id,
            COALESCE(v_referencia_nombre, 'Sin referencia') AS referencia_nombre,
            0 AS en_votacion,
            'Postulado creado exitosamente' AS mensaje;
    END ;;
DELIMITER ;
